function mappingCounts(){const m=importState;const known=detectedNames.filter((_,i)=>Number(m.maps?.[i]??(m.names?[0,1,3,4,-1][i]:-1))>=0).length;return `Сопоставлено: ${known} · новых: ${detectedNames.length-known}`;}
function bindImportMapping(){const m=importState;if(!m)return;if(m.step===3){const row=$$('#import-step-body .summary-row').find(r=>$('span',r)?.textContent==='Классы');if(row&&m.type!=='images')$('strong',row).textContent=mappingCounts();}if(m.step!==2||m.type==='images')return;const update=()=>{$$('[data-class-map]').forEach(s=>{const row=s.closest('tr'),badge=$('.badge',row.cells[3]);const name=m.names?detectedNames[Number(s.dataset.classMap)]:m.manualNames?.[Number(s.dataset.classMap)];badge.textContent=!name?'Укажите имя':s.value==='new'?'Новый':'Сопоставлен';badge.className=`badge ${s.value==='new'?'model':'good'}`;});const hint=$('#import-step-body .inline-help');if(hint)hint.textContent=mappingCounts()+'. Имена проекта сохраняются. Исходные индексы модели / датасета привязаны к выбранным классам проекта.';};$$('[data-class-map]').forEach(s=>s.onchange=()=>{m.maps=m.maps||{};m.maps[Number(s.dataset.classMap)]=s.value==='new'?-1:Number(s.value);update();});$$('[data-class-name]').forEach(input=>input.oninput=()=>{m.manualNames=m.manualNames||{};m.manualNames[Number(input.dataset.className)]=input.value.trim();update();});update();}
