const pages = [['images','Изображения','48 620','index.html'],['statistics','Статистика','','statistics.html'],['cameras','Камеры проекта','3','cameras.html'],['imports','Импорт и модели','2','imports.html'],['classes','Классы','6','classes.html']];

function scene(item = items[0], large = false) {
  const n = item.id || 1, night = item.night, accent = ['#6c87a2','#837c8f','#537f86','#8d8470'][n%4];
  const x = 200+(n%5)*13, y = 116+(n%3)*12;
  return `<svg viewBox="0 0 640 400" role="img" aria-label="Демонстрационный кадр автомобиля ${n}"><defs><linearGradient id="bg${n}${large?'v':''}" x2="0" y2="1"><stop stop-color="${night?'#111a29':'#51616d'}"/><stop offset="1" stop-color="${night?'#253142':'#333f4b'}"/></linearGradient></defs><rect width="640" height="400" fill="url(#bg${n}${large?'v':''})"/><path d="M0 84H640M0 100H640" stroke="#9ba9b61c" stroke-width="4"/><path d="M125 0V165M515 0V165" stroke="#a0b1c31c" stroke-width="16"/><path d="M0 400L230 150H410L640 400" fill="${night?'#17222e':'#2b3741'}"/><path d="M80 400L266 150M560 400L380 150" stroke="#a9b29c44" stroke-width="4"/><path d="M320 360V385M320 260V285M320 180V195" stroke="#d3d0ba44" stroke-width="5"/><path d="M${x} ${y+20}L${x+30} ${y-24}Q${x+100} ${y-38} ${x+170} ${y-24}L${x+205} ${y+22}L${x+220} ${y+42}V${y+128}H${x-14}V${y+42}Z" fill="${accent}" stroke="#a4b4c255" stroke-width="3"/><path d="M${x+32} ${y-17}H${x+168}L${x+187} ${y+25}H${x+10}Z" fill="${night?'#152534':'#263a4c'}"/><rect x="${x-9}" y="${y+113}" width="35" height="33" rx="8" fill="#111821"/><rect x="${x+179}" y="${y+113}" width="35" height="33" rx="8" fill="#111821"/><rect x="${x+44}" y="${y+58}" width="116" height="35" rx="6" fill="#1c2631"/><path d="M${x+52} ${y+66}H${x+152}M${x+52} ${y+77}H${x+152}M${x+52} ${y+88}H${x+152}" stroke="#52616f" stroke-width="3"/><rect x="${x-2}" y="${y+52}" width="45" height="24" rx="6" fill="${night?'#f5e5ad':'#d6e2e3'}"/><rect x="${x+163}" y="${y+52}" width="45" height="24" rx="6" fill="${night?'#f5e5ad':'#d6e2e3'}"/>${night?`<ellipse cx="${x+20}" cy="${y+65}" rx="58" ry="27" fill="#ffebac14"/><ellipse cx="${x+187}" cy="${y+65}" rx="58" ry="27" fill="#ffebac14"/>`:''}<rect x="${x+72}" y="${y+101}" width="62" height="15" rx="2" fill="#aeb7bd"/><path d="M${x+83} ${y+109}H${x+122}" stroke="#3b4853" stroke-width="4"/><rect x="0" y="0" width="640" height="400" fill="#09121b" opacity="${item.blur ? 0.15 : 0}"/>${item.status!=='unannotated'&&item.objects>0?`<g class="svg-box"><rect x="${x-7}" y="${y+46}" width="55" height="35" fill="${classes[item.classes[0]||0].color}20" stroke="${classes[item.classes[0]||0].color}" stroke-width="2"/><rect x="${x+157}" y="${y+46}" width="55" height="35" fill="none" stroke="${classes[item.classes[0]||0].color}" stroke-width="2"/><rect x="${x-7}" y="${y+27}" width="153" height="18" fill="${classes[item.classes[0]||0].color}"/><text x="${x-2}" y="${y+40}" font-family="Segoe UI,sans-serif" font-size="12" fill="#101a27">${esc(classes[item.classes[0]||0].name)} ${Math.round(item.confidence*100)}%</text></g>`:''}<text x="17" y="382" fill="#b7c3ce9c" font-family="Consolas,monospace" font-size="11">${String(item.day||22).padStart(2,'0')}.10.2026 · ${String(night?21+n%3:8+n%10).padStart(2,'0')}:${String(n%60).padStart(2,'0')}:12</text></svg>`;
}
function toast(message){let t=$('.toast');if(t)t.remove();t=document.createElement('div');t.className='toast';t.textContent=message;document.body.append(t);setTimeout(()=>t.remove(),4500);}
function modal(content, extra=''){closeModal();const root=document.createElement('div');root.className=`modal-backdrop ${extra}`;root.id='modal';root.innerHTML=`<section class="modal ${extra==='viewer'?'viewer-box':''}" role="dialog" aria-modal="true">${content}</section>`;root.addEventListener('click',e=>{if(e.target===root)closeModal();});document.body.append(root);$('[data-close]',root)?.addEventListener('click',closeModal);document.body.style.overflow='hidden';$('[data-close]',root)?.focus();}
function closeModal(){ $('#modal')?.remove();document.body.style.overflow=''; }
function modalHead(title,sub=''){return `<div class="modal-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div><button class="quiet small" data-close aria-label="Закрыть">✕</button></div>`;}
function heading(kicker,title,desc,actions=''){return `<header class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></header>`;}
function shell(){document.body.classList.add('show-boxes');$('#prototype').innerHTML=`<div class="shell"><aside><div class="brand">lbl<span>stdio</span></div><a class="nav-link" href="/#/projects">← Все проекты</a><a class="nav-link" href="../collection-center/index.html">▱ Центр сбора <b>12</b></a><div class="project-name"><span class="micro">ТЕКУЩИЙ ПРОЕКТ</span><strong>Световые приборы</strong><span class="micro">Детекция · 6 классов</span></div><div class="section-label">Данные проекта</div>${pages.map(([key,name,count,url])=>`<a href="${url}" class="nav-link ${page===key?'active':''}">${name}<b>${count}</b></a>`).join('')}<div class="aside-bottom"><span class="live-dot"></span>2 камеры пополняют проект<br><br><a class="link" href="imports.html">Задачи импорта →</a><br><br>Классы настраиваются здесь.<br>В разметке — выбор класса.</div></aside><div><div class="topbar"><div>Рабочее пространство <span>/</span> Световые приборы <span>/</span> Данные</div><div><button class="quiet small" id="tasks-button"><span class="task-indicator"></span>Задачи 2</button><span class="prototype-label">МАКЕТ · демоданные</span></div></div><div class="project-tabs"><span class="active">Данные</span><span>Разметка</span><span>Версии датасета</span><span>Модели и обучение</span><span>Настройки проекта</span></div><main class="main" id="content"></main></div></div>`;$('#tasks-button').onclick=openTasks;}
function metric(label,value,sub,color='',action=''){return `<div class="metric">${action?`<button data-preset="${action}">`:''}<span class="muted">${label}</span><div class="value ${color}">${value}</div><small>${sub}</small>${action?'</button>':''}</div>`;}
function group(title,content,open=false){return `<details ${open?'open':''}><summary>${title}</summary><div>${content}</div></details>`;}
function checks(name,opts){return opts.map(([value,label,count])=>`<label class="check"><input type="checkbox" data-filter="${name}" value="${value}" ${(state.filters[name]||[]).includes(String(value))?'checked':''}>${label}${count?`<em>${count}</em>`:''}</label>`).join('');}
function select(name,opts){return `<select data-filter="${name}">${opts.map(([value,label])=>`<option value="${value}" ${state.filters[name]===value?'selected':''}>${label}</option>`).join('')}</select>`;}
function filterSidebar(){return `<section class="panel filter-panel" id="filter-panel"><div class="section-head"><h2>Фильтры</h2><button class="quiet small" id="reset-filters">Сбросить</button></div><div class="filter-note">Условия разных групп объединяются через «И». Классы внутри группы — через «ИЛИ».</div>${group('Статус разметки',checks('status',Object.entries(statusNames).map(([id,name])=>[id,name,id==='verified'?'24 310':id==='unannotated'?'9 724':id==='review'?'9 724':'4 862'])),true)}${group('Камера и происхождение',select('camera',[['','Все источники'],...cameras.map(c=>[c.id,c.name]),['dataset','Импорт датасета'],['upload','Загруженные изображения']])+`<div style="height:8px"></div>`+select('origin',[['','Любая разметка'],['manual','Ручная'],['model','Предсказания модели'],['import','Из датасета']]),true)}${group('Содержимое кадра',checks('class',classes.map((c,i)=>[i,c.name]))+`<label class="check"><input data-filter="background" type="checkbox" ${state.filters.background?'checked':''}>Без объектов / фон</label><div class="field"><label class="micro">Число объектов</label><div class="actions"><input type="number" min="0" placeholder="от" data-filter="minObjects" value="${esc(state.filters.minObjects||'')}"><input type="number" min="0" placeholder="до" data-filter="maxObjects" value="${esc(state.filters.maxObjects||'')}"></div></div>`+select('objectSize',[['','Любой размер объекта'],['small','Мелкие объекты (< 2% кадра)'],['large','Крупные объекты (> 30%)']]),true)}${group('Уверенность и сложность',`<label class="micro">Уверенность модели, %</label><div class="actions" style="margin:8px 0"><input type="number" min="0" max="100" data-filter="minConf" placeholder="от" value="${esc(state.filters.minConf||'')}"><input type="number" min="0" max="100" data-filter="maxConf" placeholder="до" value="${esc(state.filters.maxConf||'')}"></div>`+checks('quality',[['night','Ночная сцена'],['blur','Смазанные / нерезкие'],['duplicate','Похожие и дубликаты']]),false)}${group('Дата и время',`<label class="field micro">С даты<input type="date" data-filter="from" value="${esc(state.filters.from||'')}"></label><label class="field micro">По дату<input type="date" data-filter="to" value="${esc(state.filters.to||'')}"></label>`+select('time',[['','Любое время'],['night','Ночь · 20:00–06:00'],['day','День · 06:00–20:00']]),false)}${group('Датасет и версии',select('split',[['','Все выборки'],['train','Train · обучение'],['val','Validation · валидация'],['test','Test · независимая проверка']])+`<div style="height:8px"></div>`+select('version',[['','Любая версия'],['v7','Входит в версию v7'],['new','Ещё не включено в версию']]),false)}${group('Свойства файла',select('resolution',[['','Любое разрешение'],['high','Больше 1920 × 1080'],['portrait','Вертикальное изображение']])+`<div style="height:8px"></div>`+select('format',[['','Все форматы'],['jpg','JPG / JPEG'],['png','PNG']]),false)}${group('Теги',select('tag',[['','Любой тег'],['ночь','Ночь'],['день','День'],['сложный случай','Сложный случай']]),false)}<button class="quiet full small" id="advanced-rules" style="margin-top:14px">Составное условие И / ИЛИ</button></section>`;}
function filterItems(){const f=state.filters;return items.filter(i=>(!f.q||i.name.includes(f.q.toLowerCase()))&&(!f.status?.length||f.status.includes(i.status))&&(!f.camera||i.camera===f.camera)&&(!f.origin||i.origin===f.origin)&&(!f.class?.length||i.classes.some(c=>f.class.includes(String(c))))&&(!f.background||(!i.objects&&i.status==='verified'))&&(!f.minObjects||i.objects>=Number(f.minObjects))&&(!f.maxObjects||i.objects<=Number(f.maxObjects))&&(!f.minConf||(i.status!=='unannotated'&&i.confidence*100>=Number(f.minConf)))&&(!f.maxConf||(i.status!=='unannotated'&&i.confidence*100<=Number(f.maxConf)))&&(!f.quality?.length||f.quality.every(k=>i[k]))&&(!f.split||i.split===f.split)&&(!f.time||(f.time==='night'?i.night:!i.night))&&(!f.from||i.date>=f.from)&&(!f.to||i.date<=f.to)&&(!f.resolution||(f.resolution==='portrait'?i.height>i.width:i.width>1920))&&(!f.format||i.format===f.format)&&(!f.tag||i.tag===f.tag)&&(!f.objectSize||(f.objectSize==='small'?i.id%4===0:i.id%4===1))&&(!f.rule||(i.confidence<=0.5||i.blur))&&(!f.version||(f.version==='new'?i.id%5===0:i.id%5!==0)));}
function renderImages(){const verified=items.filter(i=>i.status==='verified').length;$('#content').innerHTML=heading('Данные / библиотека','Изображения','Просмотр, отбор и подготовка данных проекта.',`<button class="quiet" id="camera-shortcut">＋ Камера</button><button class="quiet" data-import="model">Загрузить модель</button><button class="primary" data-import="dataset">＋ Добавить данные</button>`)+`<div class="metrics five">${metric('Всего изображений',num(items.length),'За всё время')}${metric('Готовы к обучению',num(verified),'Проверенные изображения','green','verified')}${metric('Ждут проверки','14 586','Предсказания и повторная проверка','amber','review')}${metric('Без разметки','9 724','Очередь для разметки','','unannotated')}${metric('Источники','3 камеры','2 сбора активны · +864 за сутки')}</div><div class="saved-views"><span class="micro" style="align-self:center;margin-right:5px">СОХРАНЁННЫЕ ВИДЫ</span>${[['all','Все изображения'],['review','◷ На проверку'],['rare','Редкие классы'],['night','Ночь · пост № 2'],['duplicate','Похожие кадры'],['uncertain','Уверенность < 50%'],...state.saved.map((s,i)=>['saved'+i,s.name])].map(([id,name])=>`<button data-preset="${id}">${name}</button>`).join('')}<button id="save-view">＋ Сохранить вид</button></div><div class="library">${filterSidebar()}<section><div class="toolbar"><button class="quiet filter-toggle" id="filter-toggle">Фильтры</button><input data-filter="q" value="${esc(state.filters.q||'')}" placeholder="Найти по имени файла…" aria-label="Поиск изображения"><select id="sort-images"><option value="new">Сначала новые</option><option value="old">Сначала старые</option><option value="confidence">Низкая уверенность</option><option value="objects">Больше объектов</option></select><div class="toolbar-end"><button id="boxes-toggle" class="quiet icon-btn" title="Показать или скрыть разметку">▣ Разметка</button><button id="density-toggle" class="quiet icon-btn" title="Размер миниатюр">⊞</button><button id="view-toggle" class="quiet icon-btn" title="Сетка или список">☷</button></div></div><div id="filter-pills" class="filter-pills"></div><div class="result-line"><label><input type="checkbox" id="select-page"> Выбрать страницу</label><span id="result-count"></span></div><div id="gallery" class="image-grid"></div><div class="page-controls"><span>На странице <select id="page-size"><option>24</option><option>48</option><option>96</option></select></span><div class="actions" id="pagination"></div><span id="page-range"></span></div><div class="inline-help">Один клик — быстрый просмотр с разметкой и сведениями об источнике. Стрелки ← → — следующий кадр. Переход в редактор — отдельной кнопкой.</div></section></div><div id="selection-bar" class="selection-bar hidden"></div>`;
  bindImportButtons();$('#camera-shortcut').onclick=()=>openCamera();$('#reset-filters').onclick=()=>{state.filters={};state.page=1;renderImages();};$('#filter-toggle').onclick=()=>$('#filter-panel').classList.toggle('open');$('#advanced-rules').onclick=openRules;$('#save-view').onclick=saveView;
  $$('[data-preset]').forEach(b=>b.onclick=()=>applyPreset(b.dataset.preset));
  $$('[data-filter]').forEach(el=>el.addEventListener(el.type==='search'||el.tagName==='INPUT'&&el.type!=='checkbox'?'input':'change',()=>{const key=el.dataset.filter;if(['status','class','quality'].includes(key))state.filters[key]=$$(`[data-filter="${key}"]:checked`).map(x=>x.value);else state.filters[key]=el.type==='checkbox'?el.checked:el.value;state.page=1;state.allSelected=false;updateGallery();}));
  $('#sort-images').onchange=updateGallery;$('#boxes-toggle').onclick=()=>{state.boxes=!state.boxes;document.body.classList.toggle('show-boxes',state.boxes);};$('#density-toggle').onclick=()=>{state.dense=!state.dense;updateGallery();};$('#view-toggle').onclick=()=>{state.view=state.view==='grid'?'list':'grid';updateGallery();};$('#page-size').value=state.size;$('#page-size').onchange=e=>{state.size=Number(e.target.value);state.page=1;updateGallery();};$('#select-page').onchange=e=>{matched.slice((state.page-1)*state.size,state.page*state.size).forEach(i=>e.target.checked?state.selected.add(i.id):state.selected.delete(i.id));updateGallery();};updateGallery();}
function updateGallery(){matched=filterItems();const sort=$('#sort-images')?.value;if(sort==='new')matched.reverse();if(sort==='confidence')matched.sort((a,b)=>a.confidence-b.confidence);if(sort==='objects')matched.sort((a,b)=>b.objects-a.objects);const totalPages=Math.max(1,Math.ceil(matched.length/state.size));state.page=Math.min(totalPages,state.page);const start=(state.page-1)*state.size;const visible=matched.slice(start,start+state.size);$('#gallery').className=`image-grid ${state.dense?'dense':''} ${state.view==='list'?'list':''}`;$('#gallery').innerHTML=visible.map(i=>`<article class="image-card ${state.selected.has(i.id)?'selected':''}"><input type="checkbox" class="card-check" data-select="${i.id}" aria-label="Выбрать ${i.name}" ${state.selected.has(i.id)?'checked':''}><button class="image-open" data-open="${i.id}" aria-label="Открыть ${i.name}"><div class="thumb">${scene(i)}<div class="badges"><span class="badge ${i.status==='verified'?'good':i.status==='unannotated'?'':'warn'}">${statusNames[i.status]}</span>${i.blur?'<span class="badge error">Смаз</span>':i.duplicate?'<span class="badge">Похожие</span>':''}</div></div></button><div class="card-info"><strong>${i.name}</strong><div class="sub"><span>${cameras.find(c=>c.id===i.camera)?.name||'Импорт / загрузка'}</span><span>${i.objects} obj</span></div><div class="tags">${i.classes.length?i.classes.map(c=>classes[c].name).join(' · '):'Без объектов / фон'} · ${i.split.toUpperCase()}</div></div></article>`).join('')||'<div class="panel empty full-row"><h2>По этим условиям нет изображений</h2><p>Уберите часть фильтров или сбросьте все условия.</p></div>';$('#result-count').textContent=`Найдено ${num(matched.length)} из ${num(items.length)}`;$('#page-range').textContent=matched.length?`${num(start+1)}–${num(Math.min(start+state.size,matched.length))} из ${num(matched.length)}`:'0 изображений';$('#pagination').innerHTML=`<button class="quiet small" id="prev-page" ${state.page===1?'disabled':''}>←</button><span>Страница ${state.page} из ${num(totalPages)}</span><button class="quiet small" id="next-page" ${state.page>=totalPages?'disabled':''}>→</button>`;$('#prev-page').onclick=()=>{state.page--;updateGallery();};$('#next-page').onclick=()=>{state.page++;updateGallery();};$('#select-page').checked=visible.length>0&&visible.every(i=>state.selected.has(i.id));$$('[data-open]').forEach(b=>b.onclick=()=>openViewer(Number(b.dataset.open)));$$('[data-select]').forEach(b=>b.onchange=()=>{b.checked?state.selected.add(Number(b.dataset.select)):state.selected.delete(Number(b.dataset.select));b.closest('.image-card').classList.toggle('selected',b.checked);renderSelection();});renderFilterPills();renderSelection();}
function renderFilterPills(){const names={rule:'Группа ИЛИ',q:'Имя',status:'Статус',camera:'Источник',origin:'Разметка',class:'Класс',background:'Фон',minObjects:'Объектов от',maxObjects:'Объектов до',minConf:'Уверенность от',maxConf:'Уверенность до',quality:'Качество',split:'Выборка',time:'Время',from:'С даты',to:'По дату',resolution:'Разрешение',format:'Формат',tag:'Тег',version:'Версия',objectSize:'Размер объекта'};$('#filter-pills').innerHTML=Object.entries(state.filters).filter(([,v])=>Array.isArray(v)?v.length:Boolean(v)).map(([k,v])=>{let value=Array.isArray(v)?v.map(x=>k==='class'?classes[Number(x)].name:k==='status'?statusNames[x]:{night:'ночь',blur:'смаз',duplicate:'похожие'}[x]||x).join(', '):cameras.find(c=>c.id===v)?.name||v;if(k==='rule')value='уверенность < 50% или смаз';return `<button data-clear="${k}">${names[k]}: ${v===true?'да':esc(value)} ×</button>`;}).join('');$$('[data-clear]').forEach(b=>b.onclick=()=>{delete state.filters[b.dataset.clear];state.page=1;renderImages();});}
function renderSelection(){const bar=$('#selection-bar');bar.classList.toggle('hidden',!state.selected.size&&!state.allSelected);bar.innerHTML=`<span>${state.allSelected?num(matched.length):state.selected.size} выбрано</span><button class="quiet" id="select-matching">Все ${num(matched.length)} по фильтру</button><button class="quiet" data-bulk="Добавить тег">Тег</button><button class="quiet" data-bulk="Отправить на проверку">На проверку</button><button class="quiet" data-bulk="Экспортировать выборку">Экспорт</button><button class="quiet danger" data-bulk="Переместить в корзину">В корзину</button><button class="quiet" id="clear-selection">✕</button>`;$('#select-matching').onclick=()=>{state.allSelected=true;renderSelection();};$('#clear-selection').onclick=()=>{state.allSelected=false;state.selected.clear();updateGallery();};$$('[data-bulk]').forEach(b=>b.onclick=()=>toast(`${b.dataset.bulk}: действие показано в макете, данные проекта не изменены.`));}
function applyPreset(id){state.filters=id==='verified'?{status:['verified']}:id==='unannotated'?{status:['unannotated']}:id==='review'?{status:['review','recheck']}:id==='rare'?{class:['4','5']}:id==='night'?{camera:'cam2',quality:['night']}:id==='duplicate'?{quality:['duplicate']}:id==='uncertain'?{maxConf:'50'}:id.startsWith('saved')?structuredClone(state.saved[Number(id.slice(5))].filters):{};state.page=1;renderImages();}
function saveView(){modal(modalHead('Сохранить вид','Условия, сортировка и представление будут доступны одним кликом.')+`<label class="field">Название<input id="view-name" value="Мой отбор"></label><div class="wizard-footer"><span class="micro">Личный вид · только для этого проекта</span><button class="primary" id="save-view-confirm">Сохранить вид</button></div>`);$('#save-view-confirm').onclick=()=>{state.saved.push({name:$('#view-name').value||'Мой отбор',filters:structuredClone(state.filters)});closeModal();renderImages();toast('Вид сохранён в текущем макете');};}
function openRules(){modal(modalHead('Составное условие','Для сложного отбора: объединяйте группы через И / ИЛИ.')+`<div class="rule-builder"><div class="actions"><span class="badge model">ВСЕ условия · И</span></div><div class="actions"><select><option>Статус</option></select><select><option>На проверке</option></select></div><div class="rule-builder"><span class="badge">ЛЮБОЕ условие · ИЛИ</span><div class="actions" style="margin-top:12px"><select><option>Уверенность ниже</option></select><input type="number" value="50"><span>%</span></div><div class="actions"><select><option>Качество</option></select><select><option>Смазанный кадр</option></select></div></div></div><p class="micro">Найти кадры на проверке с низкой уверенностью ИЛИ смазом.</p><div class="wizard-footer"><span class="micro">Пример сложного фильтра</span><button class="primary" id="apply-rules">Применить пример</button></div>`);$('#apply-rules').onclick=()=>{state.filters={status:['review','recheck'],rule:'uncertainOrBlur'};closeModal();renderImages();toast('Составное условие применено: статус И (уверенность < 50% ИЛИ смаз)');};}
function openViewer(id){state.viewer=id;const i=items[id-1],idx=matched.findIndex(x=>x.id===id);modal(`<div class="viewer-top"><div><strong>${i.name}</strong><span class="micro" style="margin-left:15px">${num(idx+1)} / ${num(matched.length)} в текущем отборе</span></div><div class="actions"><button class="quiet small" id="viewer-boxes">▣ Разметка</button><button class="quiet small" data-close>✕ Закрыть</button></div></div><div class="viewer-layout"><div class="viewer-media"><div class="large-frame">${scene(i,true)}</div></div><div class="viewer-info"><h3>Об изображении</h3><div class="summary-row"><span>Статус</span><strong>${statusNames[i.status]}</strong></div><div class="summary-row"><span>Источник</span><strong>${cameras.find(c=>c.id===i.camera)?.name||'Импорт датасета'}</strong></div><div class="summary-row"><span>Разрешение</span><strong>${i.width} × ${i.height}</strong></div><div class="summary-row"><span>Объекты</span><strong>${i.objects}</strong></div><div class="summary-row"><span>Уверенность</span><strong>${Math.round(i.confidence*100)}%</strong></div><div class="summary-row"><span>Выборка</span><strong>${i.split.toUpperCase()}</strong></div><div class="summary-row"><span>Происхождение</span><strong>${{manual:'Ручная разметка',model:'Модель v7',import:'Импорт YOLO',none:'Разметка отсутствует'}[i.origin]}</strong></div><h3 style="margin-top:20px">Классы в кадре</h3>${i.classes.map(c=>`<div style="margin-top:8px"><span style="color:${classes[c].color}">●</span> ${classes[c].name}</div>`).join('')||'<p class="muted">Фоновый кадр</p>'}<div class="divider"></div><span class="badge">${i.tag}</span>${i.duplicate?'<div class="inline-help">Найдено 4 похожих кадра. Сравните перед добавлением в обучающую выборку.</div>':''}<button class="primary full" id="viewer-annotate" style="margin-top:18px">Открыть в разметке ↗</button></div></div><div class="viewer-controls"><button class="quiet small" id="viewer-prev" ${idx<=0?'disabled':''}>← Предыдущий</button><span><span class="kbd">←</span> <span class="kbd">→</span> навигация · <span class="kbd">Esc</span> закрыть</span><button class="quiet small" id="viewer-next" ${idx>=matched.length-1?'disabled':''}>Следующий →</button></div>`,'viewer');$('#viewer-prev').onclick=()=>openViewer(matched[idx-1].id);$('#viewer-next').onclick=()=>openViewer(matched[idx+1].id);$('#viewer-boxes').onclick=()=>document.body.classList.toggle('show-boxes');$('#viewer-annotate').onclick=()=>toast('В реализации откроется редактор с этим кадром и текущей выборкой.');}

function trendChart(){const a=[42,64,55,79,74,62,105,97,132,114,143,157,139,174];return `<svg viewBox="0 0 700 235" role="img" aria-label="Пополнение данных за 14 дней"><g stroke="#2c3544" stroke-width="1"><path d="M42 25H680M42 75H680M42 125H680M42 175H680"/></g><g fill="#7c8ca5" font-family="Segoe UI,sans-serif" font-size="10"><text x="2" y="29">1200</text><text x="9" y="79">800</text><text x="9" y="129">400</text><text x="23" y="179">0</text></g>${a.map((v,i)=>`<rect x="${55+i*44}" y="${185-v}" width="24" height="${v}" rx="3" fill="${i===13?'#c0c8ff':'#8495dd'}" opacity="${i===13?1:.7}"/><text x="${57+i*44}" y="207" fill="#7e90aa" font-size="10" font-family="Segoe UI,sans-serif">${9+i}</text>`).join('')}<path d="M68 145L112 137L156 141L200 130L244 133L288 139L332 119L376 124L420 110L464 117L508 105L552 98L596 106L640 91" fill="none" stroke="#6ad5a9" stroke-width="2"/></svg>`;}
function renderStatistics(){const counts=classes.map((c,k)=>({c,k,count:items.filter(i=>i.classes.includes(k)).length}));$('#content').innerHTML=heading('Данные / аналитика','Состояние данных','Готовность к обучению, баланс классов и вклад каждого источника.',`<select aria-label="Период статистики"><option>Последние 14 дней</option><option>Последние 30 дней</option><option>За всё время</option></select><button class="quiet" data-demo="Отчёт будет выгружен в CSV или PDF">Скачать отчёт ↓</button>`)+`<div class="metrics">${metric('Изображений','48 620','+864 за последние сутки')}${metric('Проверено','50%','24 310 готовы к обучению','green')}${metric('Размеченных объектов','128 940','6 классов · 3,7 объекта / кадр')}${metric('Нуждаются в разборе','2 538','Смаз, повторы и конфликты','amber')}</div><div class="notice"><span class="amber">●</span><div><strong>Перед следующей версией датасета</strong><div class="micro">Есть похожие кадры между train и test; у двух классов мало ночных примеров.</div></div><a href="index.html?preset=duplicate">Разобрать →</a></div><div class="data-split"><section class="panel panel-pad"><div class="stat-topline"><h2>Как пополняется проект</h2><span class="badge good">+18% к предыдущему периоду</span></div><div class="chart">${trendChart()}</div><div class="chart-legend"><span><i></i>Получено изображений</span><span><i style="background:#6ad5a9"></i>Проверено вручную</span><span>Октябрь 2026 · UTC+4</span></div></section><section class="panel panel-pad"><div class="stat-topline"><h2>Очередь работы</h2><a class="link micro" href="index.html?preset=review">Открыть очередь →</a></div><div class="stack-bar"><i style="width:50%;background:#6ad5a9"></i><i style="width:20%;background:#7784a1"></i><i style="width:20%;background:#efc37b"></i><i style="width:10%;background:#f28f94"></i></div><div class="quality-list">${[['Проверено','24 310','verified'],['Без разметки','9 724','unannotated'],['На проверке','9 724','review'],['Повторная проверка','4 862','review']].map(([name,count,preset])=>`<a href="index.html?preset=${preset}"><span>${name}</span><span>${count} →</span></a>`).join('')}</div></section></div><div class="data-split"><section class="panel panel-pad"><div class="stat-topline"><h2>Баланс классов</h2><span class="micro">Изображения с классом · могут пересекаться</span></div><div class="bars">${counts.map(({c,k,count})=>`<a class="bar-row" href="index.html?class=${k}"><span>${c.name}</span><span class="bar-track"><i style="width:${Math.round(count/Math.max(...counts.map(row=>row.count))*100)}%;background:${c.color}"></i></span><span>${num(count)}</span></a>`).join('')}</div><div class="inline-help">Рекомендация: расширить ночную выборку для противотуманных фар и стоп-сигналов. <a href="index.html?preset=rare" class="link">Открыть редкие классы →</a></div></section><section class="panel panel-pad"><div class="stat-topline"><h2>Качество и повторы</h2><span class="badge warn">Есть что проверить</span></div><div class="quality-list"><a href="index.html?quality=blur"><span>Смазанные изображения</span><span>1 315 →</span></a><a href="index.html?preset=duplicate"><span>Группы похожих кадров</span><span>918 →</span></a><a href="index.html?preset=duplicate"><span>Пересечения train / test</span><span>32 группы →</span></a><a href="index.html?preset=uncertain"><span>Слабые предсказания модели</span><span>7 284 →</span></a><a href="imports.html"><span>Ошибки последнего импорта</span><span>7 файлов →</span></a></div><p class="micro" style="margin-top:15px">Проблемные изображения остаются доступны. Проверки помогают выбрать, что включать в следующую версию.</p></section></div><section class="panel"><div class="table-headline"><h2>Откуда поступают данные</h2><a href="cameras.html" class="link micro">Управлять камерами →</a></div><div class="table-scroll"><table class="coverage-table"><thead><tr><th>Источник</th><th>Всего кадров</th><th>За сутки</th><th>Проверено</th><th>Ночные сцены</th><th>Действие</th></tr></thead><tbody>${[...cameras,{id:'dataset',name:'Импорт датасета',count:6800},{id:'upload',name:'Ручная загрузка',count:2500}].map((c,i)=>`<tr><td><strong>${c.name}</strong><span class="micro">${i<3?'Камера проекта':'Пакеты загрузки'}</span></td><td>${num(c.count)}</td><td>${[492,372,0,0,0][i]}</td><td>${[64,52,78,90,34][i]}%</td><td>${[28,43,38,18,12][i]}%</td><td><a class="link" href="index.html?camera=${c.id}">Посмотреть кадры →</a></td></tr>`).join('')}</tbody></table></div></section>`;bindDemos();}

function renderCameras(){$('#content').innerHTML=heading('Данные / источники','Камеры проекта','Общие камеры, связанные с этим проектом, и результаты их сборов.',`<a class="quiet small link" href="../collection-center/index.html">Все сборы ↗</a><button class="primary" id="add-project-camera">＋ Подключить камеру</button>`)+`<div class="metrics">${metric('Подключено к проекту','3 камеры','Из общего каталога источников')}${metric('Активных сборов','2','Кадры поступают в этот проект','green')}${metric('За сутки','864 кадра','Последний кадр · 12 секунд назад')}${metric('Нуждаются во внимании','1 камера','Парковка · нет сигнала','amber')}</div><div class="notice neutral"><span>▱</span><div><strong>Камера общая, сбор принадлежит проекту назначения</strong><div class="micro">Один источник можно использовать в нескольких проектах. Здесь — связь с проектом и кадры; условия и работающие сборы — в центре сбора.</div></div></div><div class="camera-grid">${cameras.map((c,k)=>`<article class="panel camera-card"><div class="thumb">${scene(items[k*43+30])}<span class="badge ${k===2?'error':'good'}">${k===2?'● Нет сигнала':'● Сбор идёт'}</span></div><div class="camera-content"><div class="section-head"><h2>${c.name}</h2><span class="badge">RTSP</span></div><p class="micro" style="margin-top:0">${c.location}</p><div class="summary-row"><span>В этом проекте</span><strong>${num(c.count)} кадров</strong></div><div class="summary-row"><span>Последнее сохранение</span><strong>${['12 секунд назад','48 секунд назад','3 часа назад'][k]}</strong></div><div class="summary-row"><span>Условие сбора</span><strong>${['Стабильный объект','Пересечение линии','По интервалу · 10 с'][k]}</strong></div><div class="summary-row"><span>Другие проекты</span><strong>${[2,1,0][k]}</strong></div><div class="actions"><a class="quiet small link" href="index.html?camera=${c.id}">Посмотреть кадры</a><button class="primary small" data-collect="${c.id}">${k===2?'Проверить источник':'Новый сбор'}</button><button class="quiet small" data-camera-settings="${c.id}" aria-label="Настройки ${c.name}">⋯</button></div></div></article>`).join('')}<div class="empty-camera"><span style="font-size:26px;color:#a8b1ff">＋</span><h2>Ещё одна камера</h2><p class="micro">Выберите общий источник<br>или добавьте новый для проекта.</p><button class="quiet" id="add-project-camera-card">Подключить источник</button></div></div><section class="panel" style="margin-top:22px"><div class="table-headline"><h2>Сборы, пополняющие проект</h2><span class="micro">Работают независимо от открытой вкладки</span></div><div class="table-scroll"><table><thead><tr><th>Сбор</th><th>Источник</th><th>Модель</th><th>Последний кадр</th><th>Сохранено</th><th></th></tr></thead><tbody><tr><td><strong>Дневные проезды</strong><span class="badge good">Работает</span></td><td>Ворота · въезд</td><td>Световые приборы v7</td><td>12 секунд назад</td><td>492 сегодня</td><td><a class="link" href="../collection-center/detail.html">Условия и поток ↗</a></td></tr><tr><td><strong>Проход через пост</strong><span class="badge good">Работает</span></td><td>Пост осмотра № 2</td><td>Световые приборы v7</td><td>48 секунд назад</td><td>372 сегодня</td><td><a class="link" href="../collection-center/detail.html">Условия и поток ↗</a></td></tr></tbody></table></div></section>`;$('#add-project-camera').onclick=()=>openCamera();$('#add-project-camera-card').onclick=()=>openCamera();$$('[data-collect]').forEach(b=>b.onclick=()=>openCollection(b.dataset.collect));$$('[data-camera-settings]').forEach(b=>b.onclick=()=>openCamera(b.dataset.cameraSettings));}
function openCamera(editId=''){modal(modalHead(editId?'Камера и связь с проектом':'Подключить камеру к проекту','Световые приборы · источники доступны из общего каталога.')+`<div class="segmented" style="width:fit-content"><button class="active" data-camera-tab="existing">Выбрать существующую</button><button data-camera-tab="new">Добавить новую</button></div><div id="camera-existing"><div class="toolbar" style="margin-top:18px"><input id="camera-search" placeholder="Камера, проект или расположение…"></div><div class="camera-options" id="camera-option-list">${[{name:'Ворота · въезд',project:'Световые приборы · уже связана',checked:true},{name:'Тестовый стенд · общий план',project:'Лаборатория · доступна',checked:false},{name:'Въезд · корпус В',project:'Контроль транспорта · доступна',checked:false},{name:'Пост осмотра № 3',project:'Контроль качества · доступна',checked:false}].map((c,i)=>`<label><input type="checkbox" ${c.checked?'checked disabled':''}><span><strong>${c.name}</strong><small>${c.project}</small></span><span class="badge ${c.checked?'':'good'}" style="margin-left:auto">${c.checked?'В проекте':'Доступна'}</span></label>`).join('')}</div><div class="inline-help">Привязка камеры не запускает сбор. После подключения можно создать сбор с проектом назначения «Световые приборы».</div></div><div id="camera-new" class="hidden" style="margin-top:20px"><div class="form-grid"><label class="field">Название<input placeholder="Например: Ворота · запад"></label><label class="field">Тип<select id="new-camera-type"><option value="rtsp">RTSP-камера</option><option value="device">USB / веб-камера</option><option value="video">Видеофайл</option></select></label></div><div id="camera-connection"><label class="field">Адрес потока<input placeholder="rtsp://camera.local:554/live"></label><div class="form-grid"><label class="field">Пользователь<input autocomplete="off" placeholder="Если требуется"></label><label class="field">Пароль<input type="password" autocomplete="new-password" placeholder="Если требуется"></label></div></div><label class="check"><input type="checkbox" checked> Добавить в общий каталог и связать с этим проектом</label></div><div class="wizard-footer"><span class="micro">Макет: подключения не выполняются</span><button class="primary" id="link-camera">Подключить к проекту</button></div>`);$$('[data-camera-tab]').forEach(b=>b.onclick=()=>{$$('[data-camera-tab]').forEach(x=>x.classList.toggle('active',x===b));$('#camera-existing').classList.toggle('hidden',b.dataset.cameraTab!=='existing');$('#camera-new').classList.toggle('hidden',b.dataset.cameraTab!=='new');});$('#camera-search').oninput=e=>{$$('#camera-option-list label').forEach(l=>l.classList.toggle('hidden',!l.textContent.toLowerCase().includes(e.target.value.toLowerCase())));};bindCameraType();$('#link-camera').onclick=()=>{closeModal();toast('В реализации источник будет связан с проектом. Сбор запускается отдельно.');};}
function openCollection(id){const c=cameras.find(x=>x.id===id);modal(modalHead('Новый сбор из проекта',c.name)+`<div class="summary-row"><span>Камера</span><strong>${c.name}</strong></div><div class="summary-row"><span>Куда сохранять</span><strong>Световые приборы</strong></div><div class="summary-row"><span>Доступная модель</span><strong>Световые приборы v7</strong></div><div class="inline-help">Центр сбора откроется с выбранными камерой и проектом. Там задаются условия, линия и расписание.</div><div class="wizard-footer"><button class="quiet" data-close>Отмена</button><a class="primary" href="../collection-center/new.html" style="padding:9px 13px;border-radius:7px">Посмотреть мастер центра сбора ↗</a></div>`);$$('[data-close]').forEach(b=>b.onclick=closeModal);}

function renderImports(){$('#content').innerHTML=heading('Данные / поступление','Импорт и модели','Добавляйте данные и переносите классы с предварительной проверкой.',`<button class="quiet" id="import-history">История операций</button>`)+`<div class="import-cards"><button class="import-card" data-import="images"><div class="symbol">▧</div><h2>Изображения</h2><p>Файлы, папка или архив. Отбор дубликатов, теги и происхождение перед загрузкой.</p><footer>JPG · PNG · WEBP · папка · ZIP →</footer></button><button class="import-card" data-import="dataset"><div class="symbol">▤</div><h2>Размеченный датасет</h2><p>Изображения вместе с разметкой. Найдём имена классов и сопоставим их с проектом.</p><footer>YOLO · COCO Detection · папки классов →</footer></button><button class="import-card" data-import="model"><div class="symbol">◈</div><h2>Готовая модель</h2><p>Подхватим names из модели. Если имён нет — загрузите файл классов или задайте вручную.</p><footer>Ultralytics YOLO .pt · встроенные names →</footer></button></div><div class="notice neutral"><span>↔</span><div><strong>Общий словарь классов проекта</strong><div class="micro">Импорт не заменяет существующие классы молча. Сначала показываем найденные имена, совпадения и новые классы.</div></div><a href="classes.html">Открыть классы →</a></div><section class="panel"><div class="table-headline"><h2>Последние импорты</h2><span class="micro">Загрузка и проверки выполняются в фоне</span></div><div class="table-scroll"><table><thead><tr><th>Пакет</th><th>Тип</th><th>Содержимое</th><th>Классы</th><th>Состояние</th><th></th></tr></thead><tbody><tr><td><strong>night_shift_oct22.zip</strong><span class="micro">Сегодня · 14:25</span></td><td>YOLO Detection</td><td>3 200 изображений · 11 492 объекта</td><td>4 совпадения · 1 новый</td><td><span class="badge model">Импорт · 64%</span><div class="progress"><i style="width:64%"></i></div></td><td><button class="quiet small" data-job="active">Подробнее</button></td></tr><tr><td><strong>headlights_coco_v3.zip</strong><span class="micro">Вчера · 18:10</span></td><td>COCO Detection</td><td>6 800 изображений · 21 430 объектов</td><td>6 сопоставлено</td><td><span class="badge good">Завершён</span><span class="micro">28 повторов · 7 файлов пропущено</span></td><td><button class="quiet small" data-job="report">Отчёт</button></td></tr><tr><td><strong>Дополнительные ночные кадры</strong><span class="micro">Вчера · 15:40</span></td><td>Папка изображений</td><td>2 500 изображений</td><td>Без разметки</td><td><span class="badge good">Завершён</span></td><td><a class="link" href="index.html?camera=upload">Показать →</a></td></tr></tbody></table></div></section><section class="panel models-table"><div class="table-headline"><h2>Модели проекта</h2><button class="quiet small" data-import="model">＋ Загрузить модель</button></div><div class="table-scroll"><table><thead><tr><th>Модель</th><th>Тип</th><th>Классы из модели</th><th>Сопоставление с проектом</th><th>Использование</th><th></th></tr></thead><tbody><tr><td><strong>Световые приборы v7</strong><span class="micro">Обучена в проекте · 21 октября</span></td><td>YOLO · detection</td><td>6 · names в весах</td><td><span class="badge good">6 из 6</span></td><td>2 активных сбора</td><td><button class="quiet small" data-model-map>Посмотреть классы</button></td></tr><tr><td><strong>Headlights external v2</strong><span class="micro">Загружена · 19 октября</span></td><td>YOLO · detection</td><td>5 · names в весах</td><td><span class="badge warn">Нужно сопоставить 1 класс</span></td><td>Не используется</td><td><button class="quiet small" data-model-map>Сопоставить →</button></td></tr></tbody></table></div></section><div class="format-help"><p><strong>Откуда берутся названия:</strong> YOLO — data.yaml / classes.txt; COCO — categories; классификация — имена папок; модель — names / metadata.</p><p>Если имён в источнике нет, импорт останавливается на шаге классов и предлагает файл со словарём или ручной ввод.</p></div>`;bindImportButtons();$('#import-history').onclick=openTasks;$$('[data-job]').forEach(b=>b.onclick=openTasks);$$('[data-model-map]').forEach(b=>b.onclick=()=>{importState={type:'model',step:2,format:'yolo',file:'headlights_external_v2.pt',names:true};renderImportWizard();});}
function bindImportButtons(){$$('[data-import]').forEach(b=>b.onclick=()=>openImport(b.dataset.import));}
function openImport(type){importState={type,step:0,format:'yolo',file:type==='model'?'headlights_external_v2.pt':type==='dataset'?'night_shift_oct22.zip':'night_frames.zip',names:true};renderImportWizard();}
function importFilesStep(){const m=importState;return `<h3>Выберите источник</h3>${m.type==='dataset'?`<label class="field">Формат<select id="dataset-format"><option value="yolo">YOLO Detection · ZIP с images, labels и data.yaml</option><option value="coco">COCO Detection · изображения и JSON с categories</option><option value="classification" disabled>Классификация · папки с названиями классов</option></select></label>`:''}<div class="import-source"><span style="font-size:26px;color:#a8b1ff">⇧</span><strong>${m.type==='model'?'Файл модели и необязательный словарь':m.type==='dataset'?'Архив размеченного датасета':'Изображения, папка или архив'}</strong><p>${m.type==='model'?'Веса Ultralytics YOLO .pt. Имена будут прочитаны из names.':m.type==='dataset'?'Имена классов прочитаем из описания датасета.':'При большом объёме загрузка продолжится в фоне.'}</p><input type="file" id="mock-file" aria-label="Выбрать файл для примера"><div class="badge model" style="margin-top:15px" id="mock-filename">Демо-файл: ${m.file}</div></div>${m.type==='model'?`<div class="segmented"><button data-names="yes" class="${m.names?'active':''}">Пример: имена встроены</button><button data-names="no" class="${m.names?'':'active'}">Пример: имён нет</button></div><div class="inline-help">Названия из names будут показаны перед добавлением модели. Порядок её выходных классов сохраняется.</div>`:`<div class="form-grid"><label class="field">Тег для пакета<input value="${m.type==='dataset'?'ночная смена · октябрь':'новая загрузка'}"></label><label class="field">Повторы<select><option>Пропустить точные дубликаты</option><option>Показать перед импортом</option><option>Загрузить все файлы</option></select></label></div>`}<p class="micro">Интерактивный макет: выбранные файлы никуда не отправляются. Разбор показан на демонстрационном примере.</p>`;}
function importCheckStep(){const m=importState;if(m.type==='model')return `<h3>Проверка модели</h3><div class="model-summary"><div class="mini-panel"><span class="micro">Задача</span><b>Detection</b><span class="badge good">Совпадает с проектом</span></div><div class="mini-panel"><span class="micro">Классов на выходе</span><b>5 классов</b><span class="micro">Порядок 0 → 4</span></div><div class="mini-panel"><span class="micro">Источник имён</span><b>${m.names?'model.names':'Не найден'}</b><span class="badge ${m.names?'good':'warn'}">${m.names?'Можно сопоставить':'Нужен словарь'}</span></div></div><div class="file-tree">${esc(m.file)}<br>task: detect<br>input: 640 × 640<br>names: ${m.names?"{0: low_beam, 1: high_beam, 2: turn_signal, 3: fog_light, 4: license_plate}":'отсутствуют'}</div><div class="inline-help">${m.names?'Четыре имени уже соответствуют классам проекта; для license_plate предложим создать класс.':'На следующем шаге можно приложить data.yaml / classes.txt или вручную назвать пять выходных классов.'}</div>`;return `<h3>Содержимое и проверки</h3><div class="model-summary"><div class="mini-panel"><span class="micro">Изображения</span><b>${m.type==='images'?'2 500':'3 200'}</b><span class="micro">JPG · 1920 × 1080</span></div><div class="mini-panel"><span class="micro">Разметка</span><b>${m.type==='images'?'Отсутствует':'11 492 объекта'}</b><span class="micro">${m.type==='images'?'Новые кадры без разметки':'5 классов · прямоугольники'}</span></div><div class="mini-panel"><span class="micro">Результат проверки</span><b class="amber">35 замечаний</b><span class="micro">28 повторов · 7 ошибок</span></div></div><div class="import-preview"><div class="file-tree">${m.format==='coco'?'dataset/<br>　images/ · 3 200 файлов<br>　annotations.json<br>　　categories · 5 имён<br>　　annotations · 11 492 объекта':m.type==='images'?'night_frames/<br>　camera_001.jpg<br>　camera_002.jpg<br>　… 2 500 изображений':m.format==='classification'?'dataset/<br>　low_beam/<br>　high_beam/<br>　turn_signal/<br>　fog_light/<br>　license_plate/':'dataset/<br>　data.yaml ← имена классов<br>　images/train/ · 2 240 файлов<br>　images/val/ · 640 файлов<br>　images/test/ · 320 файлов<br>　labels/ · YOLO TXT'}</div><div class="quality-list"><div class="ok-box" style="margin-top:0">✓ Задача и формат разметки совместимы</div><div class="mini-panel"><strong class="amber">28 точных повторов</strong><p>Будут пропущены. Уже есть в этом проекте.</p></div><div class="mini-panel"><strong class="amber">7 файлов с ошибками</strong><p>Выход боксов за границы или отсутствующее изображение. Пропустить и сохранить отчёт.</p></div></div></div><div class="form-grid" style="margin-top:18px"><label class="field">Состояние новой разметки<select><option>На проверке — рекомендуем</option><option>Считать проверенной</option></select></label><label class="field">Разделение на выборки<select><option>Сохранить train / val / test из датасета</option><option>Пока не назначать выборку</option></select></label></div>`;}
const detectedNames=['low_beam','high_beam','turn_signal','fog_light','license_plate'];
function importClassesStep(){const m=importState;if(m.type==='images')return `<h3>Классы не требуются для загрузки изображений</h3><div class="ok-box">Новые кадры попадут в «Без разметки». Существующие классы проекта сохранятся.</div><p class="micro">Присвоить классы можно будет в редакторе или авторазметкой модели.</p>`;return `<h3>${m.names?'Найдены названия классов':'Назовите выходные классы модели'}</h3><p class="muted" style="font-size:11px">${m.names?'Сопоставьте исходные ID с классами проекта. Разные имена не означают разные классы.':'Имена не удалось извлечь. Пустые названия не будут автоматически превращены в class_0.'}</p>${!m.names?`<div class="notice"><span>!</span><div>В модели нет names. Приложите словарь или заполните названия ниже.</div><button class="quiet small" id="sample-class-file">Использовать classes.txt · пример</button></div>`:''}<div class="panel table-scroll"><table class="mapping"><thead><tr><th>ID в ${m.type==='model'?'модели':'датасете'}</th><th>Найденное название</th><th>Класс проекта</th><th>Решение</th></tr></thead><tbody>${detectedNames.map((name,i)=>{const target=Number(m.maps?.[i]??(m.names?[0,1,3,4,-1][i]:-1));return `<tr><td><span class="badge">${i}</span></td><td>${m.names?`<strong>${name}</strong>`:`<input data-class-name="${i}" value="${esc(m.manualNames?.[i]||'')}" placeholder="Название класса ${i}" aria-label="Название выходного класса ${i}">`}</td><td><select data-class-map="${i}"><option value="new" ${target<0?'selected':''}>＋ Создать новый класс</option>${classes.map((c,k)=>`<option value="${k}" ${target===k?'selected':''}>${k} · ${c.name}</option>`).join('')}</select></td><td><span class="badge ${target<0?'model':'good'}">${target<0?'Новый':'Совпадение'}</span></td></tr>`;}).join('')}</tbody></table></div><div class="inline-help">4 класса связаны с существующими, 1 будет создан. Существующие названия проекта не переименовываются. ${m.type==='model'?'Связь сохраняется по исходным индексам модели.':'Индексы разметки будут переведены в классы проекта.'}</div><label class="check"><input type="checkbox" checked> Добавить найденные названия как альтернативные имена классов</label>`;}
function importConfirmStep(){const m=importState;return `<h3>Всё готово к ${m.type==='model'?'добавлению модели':'импорту'}</h3><div class="summary-row"><span>Проект</span><strong>Световые приборы</strong></div><div class="summary-row"><span>Источник</span><strong>${esc(m.file)}</strong></div><div class="summary-row"><span>${m.type==='model'?'Модель':'Новые изображения'}</span><strong>${m.type==='model'?'Detection · новая версия':m.type==='images'?'2 465 изображений':'3 165 изображений · 11 460 объектов'}</strong></div><div class="summary-row"><span>Классы</span><strong>${m.type==='images'?'Без изменений':'4 сопоставлено · 1 новый'}</strong></div><div class="summary-row"><span>${m.type==='model'?'Использование':'Разметка после импорта'}</span><strong>${m.type==='model'?'Доступна для выбора, сборы не запускаются':m.type==='images'?'Без разметки':'На проверке'}</strong></div><div class="ok-box">${m.type==='model'?'✓ Модель и соответствия классов будут сохранены в проекте.':'✓ Операция продолжится в фоне. Можно работать с другими изображениями.'}</div><p class="micro">В этом макете финальная кнопка только показывает результат операции. Файлы и данные проекта не изменяются.</p>`;}
function renderImportWizard(){const m=importState;const title={dataset:'Импорт размеченного датасета',model:'Загрузка модели',images:'Загрузка изображений'}[m.type];modal(modalHead(title,'Световые приборы · сначала проверка и классы, затем добавление.')+`<div class="steps">${['Файл','Проверка','Классы','Подтверждение'].map((name,k)=>`<button class="step ${k===m.step?'active':k<m.step?'done':''}" data-import-step="${k}" ${k>m.step?'disabled':''}><i>${k<m.step?'✓':k+1}</i>${name}</button>`).join('')}</div><div id="import-step-body">${[importFilesStep,importCheckStep,importClassesStep,importConfirmStep][m.step]()}</div><div class="wizard-footer"><button class="quiet" id="import-back">${m.step?'← Назад':'Отмена'}</button><span class="micro">${m.step+1} / 4</span><button class="primary" id="import-next">${m.step===3?m.type==='model'?'Добавить модель':'Запустить импорт в фоне':m.step===0?'Проверить содержимое →':'Продолжить →'}</button></div>`);$('#import-back').onclick=()=>{if(m.step){m.step--;renderImportWizard();}else closeModal();};$$('[data-import-step]').forEach(b=>b.onclick=()=>{m.step=Number(b.dataset.importStep);renderImportWizard();});$('#mock-file')?.addEventListener('change',e=>{if(e.target.files[0]){m.file=e.target.files[0].name;$('#mock-filename').textContent='Выбран: '+m.file;}});$('#dataset-format')?.addEventListener('change',e=>m.format=e.target.value);if($('#dataset-format'))$('#dataset-format').value=m.format;$$('[data-names]').forEach(b=>b.onclick=()=>{m.names=b.dataset.names==='yes';renderImportWizard();});$('#sample-class-file')?.addEventListener('click',()=>{m.names=true;m.maps=undefined;renderImportWizard();toast('Демонстрационный словарь: 5 имён прочитаны из classes.txt');});$('#import-next').onclick=()=>{if(m.step===2&&!m.names&&m.type==='model'&&$$('[data-class-name]').some(e=>!e.value.trim())){toast('Заполните все пять названий или приложите файл классов');return;}if(m.step<3){m.step++;renderImportWizard();}else{state.lastJob=m.type==='model'?'Модель добавлена · сопоставление классов сохранено':'Импорт запущен в фоне · 3 165 новых изображений';closeModal();toast(state.lastJob+' — демонстрация');openTasks();}};bindImportMapping();}

function renderClasses(){$('#content').innerHTML=heading('Данные / словарь','Классы проекта','Единые названия для разметки, импортированных датасетов и моделей.',`<button class="quiet" id="classes-from-file">Импортировать словарь</button><button class="primary" id="add-class">＋ Добавить классы</button>`)+`<div class="metrics">${metric('Классов',String(classes.length),'Общий словарь проекта')}${metric('Альтернативных имён','12','Связи с импортированными моделями')}${metric('Моделей со словарём','7','Исходные индексы сохранены')}${metric('Нужно сопоставить','1 класс','Во внешней модели','amber')}</div><div class="class-workspace"><section><div class="toolbar"><input id="class-search" placeholder="Найти класс или альтернативное имя…"><button class="quiet small" id="save-class-names">Сохранить названия</button></div><div class="panel table-scroll"><table class="class-list"><thead><tr><th>ID проекта</th><th>Цвет и название</th><th>Альтернативные имена</th><th>Изображения</th><th>Объекты</th><th></th></tr></thead><tbody>${classes.map((c,k)=>`<tr data-class-row><td><span class="badge">${k}</span></td><td><div class="class-name"><input type="color" value="${c.color}" aria-label="Цвет ${c.name}"><input type="text" data-edit-class="${k}" value="${c.name}" aria-label="Название класса ${k}"></div></td><td><span class="badge model">${c.code}</span><span class="micro">${['front_low','front_high','dho','indicator','front_fog','rear_stop'][k]||'—'}</span></td><td><a href="index.html?class=${k}" class="link">${num(items.filter(i=>i.classes.includes(k)).length)}</a></td><td>${num([34820,29160,22380,17420,8620,6540][k]||0)}</td><td><button class="quiet small" data-class-more="${k}">Связи</button></td></tr>`).join('')}</tbody></table></div><p class="micro" style="margin:13px 0">Нажмите на название или цвет для изменения. ID проекта остаётся постоянным; сопоставления с индексами моделей сохраняются.</p><section class="panel panel-pad" style="margin-top:22px"><div class="section-head"><h2>Имена во внешних источниках</h2><button class="quiet small" id="manage-mapping">Сопоставить модель</button></div><div class="summary-row"><span>YOLO dataset · low_beam →</span><strong>Ближний свет</strong></div><div class="summary-row"><span>Модель v7 · индекс 0 →</span><strong>Ближний свет</strong></div><div class="summary-row"><span>External v2 · license_plate →</span><strong class="amber">Нужно выбрать класс проекта</strong></div></section></section><div class="stat-stack" style="align-self:start"><section class="mini-panel"><h3>Здесь — управление классами</h3><p>Добавление, переименование, цвет и альтернативные названия находятся в «Данных». В редакторе разметки остаётся быстрый выбор из этого словаря.</p></section><section class="mini-panel"><h3>Ручной ввод списком</h3><p>По одному имени на строку. Перед созданием проверим повторы.</p><button class="quiet full small" id="bulk-classes" style="margin-top:14px">Вставить список</button></section><section class="mini-panel"><h3>Классы из файла</h3><p>data.yaml, classes.txt, COCO categories или names из модели. Найденные имена сначала проходят сопоставление.</p><button class="quiet full small" data-import="model" style="margin-top:14px">Прочитать из модели</button></section><section class="mini-panel"><h3>Фон — отдельный признак</h3><p>Кадр без объектов не требует фиктивного класса «background». Его можно отфильтровать в галерее.</p><a href="index.html?background=true" class="link micro">Посмотреть фоновые кадры →</a></section></div></div>`;bindImportButtons();$('#add-class').onclick=openClassInput;$('#bulk-classes').onclick=openClassInput;$('#classes-from-file').onclick=openDictionary;$('#manage-mapping').onclick=()=>{importState={type:'model',step:2,names:true,file:'headlights_external_v2.pt'};renderImportWizard();};$('#class-search').oninput=e=>{$$('[data-class-row]').forEach(r=>r.classList.toggle('hidden',![r.textContent,...$$('input',r).map(x=>x.value)].join(' ').toLowerCase().includes(e.target.value.toLowerCase())));};$('#save-class-names').onclick=()=>{const edits=$$('[data-edit-class]');const names=edits.map(e=>e.value.trim());if(names.some(n=>!n)||new Set(names.map(n=>n.toLowerCase())).size!==names.length){toast('Названия должны быть заполнены и не повторяться');return;}edits.forEach(e=>classes[Number(e.dataset.editClass)].name=e.value.trim());toast('Названия сохранены в текущем макете. Данные проекта не изменены.');};$$('[data-class-more]').forEach(b=>b.onclick=()=>openClassLinks(Number(b.dataset.classMore)));const nav=$('.nav-link[href="classes.html"] b');if(nav)nav.textContent=classes.length;const projectLabel=$$('.project-name .micro').at(-1);if(projectLabel)projectLabel.textContent=`Детекция · ${classes.length} классов`;}
function openClassInput(){modal(modalHead('Добавить классы','Введите по одному имени на строку или вставьте готовый список.')+`<textarea id="new-class-list" rows="7" placeholder="Подсветка номера\nЗадний ход\nАварийная сигнализация"></textarea><div id="class-input-feedback" class="inline-help">Проверим пустые строки и совпадения с существующими именами.</div><div class="wizard-footer"><span class="micro">Существующие ID не меняются</span><button class="primary" id="create-classes">Добавить классы</button></div>`);$('#new-class-list').oninput=e=>{const names=e.target.value.split('\n').map(x=>x.trim()).filter(Boolean),existing=[...new Set(names.map(n=>n.toLowerCase()))].filter(n=>classes.some(c=>c.name.toLowerCase()===n.toLowerCase())),unique=[...new Set(names.map(n=>n.toLowerCase()))];$('#class-input-feedback').textContent=`Новых: ${unique.length-existing.length}. Совпадений с проектом: ${existing.length}. Повторов в списке: ${names.length-unique.length}.`;};$('#create-classes').onclick=()=>{const names=$('#new-class-list').value.split('\n').map(x=>x.trim()).filter(Boolean);if(!names.length){toast('Введите хотя бы одно название');return;}let added=0;names.forEach(name=>{if(!classes.some(c=>c.name.toLowerCase()===name.toLowerCase())){classes.push({name,code:name,color:'#a8b1ff'});added++;}});closeModal();renderClasses();toast(`Добавлено ${added} классов в демонстрационный словарь`);};}
function openClassLinks(k){const c=classes[k];modal(modalHead(`Связи класса «${c.name}»`,'Проектный класс и его имена в источниках.')+`<div class="summary-row"><span>ID проекта</span><strong>${k}</strong></div><div class="summary-row"><span>Основное имя</span><strong>${c.name}</strong></div><div class="summary-row"><span>YOLO import</span><strong>${c.code}</strong></div><div class="summary-row"><span>Модель v7</span><strong>Индекс ${k} · ${c.code}</strong></div><div class="summary-row"><span>External v2</span><strong>Сопоставлен по имени</strong></div><div class="inline-help">Переименование класса меняет отображаемое название в проекте. Исходные индексы и названия в весах модели сохраняются.</div><button class="quiet" data-demo="Объединение откроет отдельный предварительный просмотр затронутой разметки и моделей">Объединить с другим классом…</button>`);bindDemos();}
function openTasks(){modal(modalHead('Операции с данными','Загрузки не блокируют просмотр проекта.')+`<div class="job-log">${state.lastJob?`<div><span class="badge good">Новая операция · демо</span><strong style="margin-top:8px">${state.lastJob}</strong><p>Это демонстрация результата, реальные файлы не обрабатывались.</p></div>`:''}<div><span class="badge model">Выполняется · 64%</span><strong style="margin-top:8px">night_shift_oct22.zip</strong><p>2 048 / 3 200 изображений · ещё около минуты</p><div class="progress"><i style="width:64%"></i></div><div class="actions" style="margin-top:12px"><button class="quiet small" data-demo="В реализации операция будет приостановлена">Пауза</button><button class="quiet small" data-demo="В реализации отмена покажет, какие файлы уже добавлены">Отменить…</button></div></div><div><span class="badge good">Завершено с замечаниями</span><strong style="margin-top:8px">headlights_coco_v3.zip</strong><p>Добавлено 6 765 кадров. Пропущено 28 точных повторов и 7 файлов с ошибками.</p><div class="actions"><a href="index.html?camera=dataset" class="link small">Открыть пакет →</a><button class="quiet small" data-demo="Отчёт: 28 дубликатов; 4 бокса за границами; 3 отсутствующих изображения">Отчёт об ошибках</button><button class="quiet small" data-demo="Откат импорта переместит только этот пакет в корзину с предварительным подтверждением">Отменить импорт…</button></div></div></div>`);bindDemos();}
function bindDemos(){$$('[data-demo]').forEach(b=>b.onclick=()=>toast(b.dataset.demo));}
function bindCameraType(){const select=$('#new-camera-type'),fields=$('#camera-connection');if(!select||!fields)return;const rtsp=fields.innerHTML;select.onchange=()=>{fields.innerHTML=select.value==='rtsp'?rtsp:select.value==='device'?'<label class="field">Номер устройства<input type="number" min="0" value="0" aria-label="Номер устройства камеры"></label><p class="micro">Камера, подключённая к компьютеру, на котором работает сервер.</p>':'<label class="field">Видеофайл<input type="file" accept="video/*" aria-label="Видеофайл источника"></label><p class="micro">Файл будет источником кадров. Условие сохранения задаётся в центре сбора.</p>';};}
function openDictionary(){modal(modalHead('Импорт словаря классов','Отдельно от изображений и весов модели.')+`<div class="import-source"><strong>data.yaml · classes.txt · COCO JSON</strong><p>В макете показан пример чтения словаря. Выбранный файл не отправляется на сервер.</p><input type="file" accept=".yaml,.yml,.txt,.json" aria-label="Файл со словарём классов"></div><div class="panel"><table class="mapping"><thead><tr><th>Исходное имя</th><th>Класс проекта</th><th>Решение</th></tr></thead><tbody>${detectedNames.map((name,k)=>`<tr><td>${name}</td><td>${k===4?'Подсветка номера':classes[[0,1,3,4][k]].name}</td><td><span class="badge ${k===4?'model':'good'}">${k===4?'Создать':'Связать с существующим'}</span></td></tr>`).join('')}</tbody></table></div><div class="wizard-footer"><span class="micro">Демо-словарь: 4 совпадения · 1 новый класс</span><button class="primary" id="dictionary-apply">Применить пример словаря</button></div>`);$('#dictionary-apply').onclick=()=>{if(!classes.some(c=>c.code==='license_plate'))classes.push({name:'Подсветка номера',code:'license_plate',color:'#78bce8'});closeModal();renderClasses();toast('Пример словаря применён только в макете');};}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(!$('.viewer-box')||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;const idx=matched.findIndex(i=>i.id===state.viewer);if(e.key==='ArrowRight'&&idx<matched.length-1){e.preventDefault();openViewer(matched[idx+1].id);}if(e.key==='ArrowLeft'&&idx>0){e.preventDefault();openViewer(matched[idx-1].id);}});
shell();
if(page==='images'){const q=new URLSearchParams(location.search);if(q.has('camera'))state.filters.camera=q.get('camera');if(q.has('class'))state.filters.class=[q.get('class')];if(q.has('quality'))state.filters.quality=[q.get('quality')];if(q.has('background'))state.filters.background=true;if(q.has('preset'))applyPreset(q.get('preset'));else renderImages();}
else if(page==='statistics')renderStatistics();else if(page==='cameras')renderCameras();else if(page==='imports')renderImports();else if(page==='classes')renderClasses();
